<div class="page-header"><h1 class="h3 mb-0"><?=($mode??'create')==='edit'?'Edit Expense':'Add Expense'?></h1><a href="<?=url('expenses')?>" class="btn btn-outline-secondary">Back</a></div><div class="card"><div class="card-body"><form method="post" enctype="multipart/form-data" action="<?=url(($mode??'create')==='edit'?'expenses/'.$expense['id']:'expenses')?>"><?=csrf_field()?><div class="row"><div class="col-md-4 mb-3"><label class="form-label">Amount *</label><input type="number" step="0.01" min="0.01" class="form-control" name="amount" required value="<?=e($expense['amount']??old('amount'))?>"></div><div class="col-md-4 mb-3"><label class="form-label">Expense Date *</label><input type="date" class="form-control" name="expense_date" required value="<?=e($expense['expense_date']??old('expense_date',date('Y-m-d')))?>"></div><div class="col-md-4 mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="posted" <?=selected($expense['status']??'posted','posted')?>>Posted</option><option value="draft" <?=selected($expense['status']??'','draft')?>>Draft</option></select></div><div class="col-md-6 mb-3"><label class="form-label">Category *</label><select class="form-select" name="category_id" required><option value="">Select category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=selected($expense['category_id']??old('category_id'),$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Account *</label><select class="form-select" name="account_id" required><option value="">Select account</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=selected($expense['account_id']??old('account_id'),$a['id'])?>><?=e($a['name'])?> (<?=money($a['current_balance'])?>)</option><?php endforeach;?></select></div><div class="col-12 mb-3"><label class="form-label">Description *</label><input class="form-control" name="descrip